package com.example.lending.adapter.in.web;

import com.example.lending.application.port.in.GetLoanUseCase;
import com.example.lending.application.port.in.LoanBookUseCase;
import com.example.lending.application.port.in.LoanBookUseCase.LoanBookCommand;
import com.example.lending.application.port.in.ReturnLoanUseCase;
import com.example.lending.application.port.in.ReturnLoanUseCase.ReturnLoanCommand;
import com.example.lending.domain.Loan;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

import java.time.LocalDate;
import java.util.UUID;

@RestController
@RequestMapping("/loans")
public class LoanController {

    private final LoanBookUseCase loanBookUseCase;
    private final ReturnLoanUseCase returnLoanUseCase;
    private final GetLoanUseCase getLoanUseCase;

    public LoanController(LoanBookUseCase loanBookUseCase, ReturnLoanUseCase returnLoanUseCase,
                          GetLoanUseCase getLoanUseCase) {
        this.loanBookUseCase = loanBookUseCase;
        this.returnLoanUseCase = returnLoanUseCase;
        this.getLoanUseCase = getLoanUseCase;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public LoanResponse loanBook(@RequestBody LoanRequest request) {
        Loan loan = loanBookUseCase.loanBook(new LoanBookCommand(request.bookId(), request.memberId(), request.loanedAt()));
        return LoanResponse.from(loan);
    }

    @GetMapping("/{loanId}")
    public LoanDetailResponse getLoan(@PathVariable UUID loanId) {
        return LoanDetailResponse.from(getLoanUseCase.getLoan(loanId));
    }

    @PostMapping("/{loanId}/return")
    public ReturnLoanResponse returnLoan(@PathVariable UUID loanId,
                                         @RequestBody(required = false) ReturnLoanRequest request) {
        LocalDate returnedAt = request == null ? null : request.returnedAt();
        Loan loan = returnLoanUseCase.returnLoan(new ReturnLoanCommand(loanId, returnedAt));
        return ReturnLoanResponse.from(loan);
    }
}

