package com.example.lending.application.service;

import com.example.lending.application.port.in.ListLoanHistoryUseCase;
import com.example.lending.application.port.out.LoadBookPort;
import com.example.lending.application.port.out.LoadLoanPort;
import com.example.lending.application.port.out.LoadMemberPort;
import com.example.lending.domain.Book;
import com.example.lending.domain.BookNotFoundException;
import com.example.lending.domain.Loan;
import com.example.lending.domain.Member;
import com.example.lending.domain.MemberNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import java.util.stream.Collectors;

@Service
@Transactional(readOnly = true)
public class ListLoanHistoryService implements ListLoanHistoryUseCase {

    private final LoadMemberPort loadMemberPort;
    private final LoadLoanPort loadLoanPort;
    private final LoadBookPort loadBookPort;

    public ListLoanHistoryService(LoadMemberPort loadMemberPort, LoadLoanPort loadLoanPort, LoadBookPort loadBookPort) {
        this.loadMemberPort = loadMemberPort;
        this.loadLoanPort = loadLoanPort;
        this.loadBookPort = loadBookPort;
    }

    @Override
    public List<LoanHistoryItem> listLoanHistory(UUID memberId) {
        Member member = loadMemberPort.loadMember(memberId)
                .orElseThrow(() -> new MemberNotFoundException(memberId));
        List<Loan> loans = loadLoanPort.loadLoanHistory(member.getId());

        Map<UUID, String> titles = loadTitles(loans);
        return loans.stream()
                .map(loan -> toItem(loan, titles))
                .toList();
    }

    private Map<UUID, String> loadTitles(List<Loan> loans) {
        Set<UUID> bookIds = loans.stream().map(Loan::getBookId).collect(Collectors.toSet());
        return loadBookPort.loadBooks(bookIds).stream()
                .collect(Collectors.toMap(Book::getId, Book::getTitle));
    }

    /** 반납되지 않은 대출은 연체료를 계산하지 않고 null 로 둔다. */
    private LoanHistoryItem toItem(Loan loan, Map<UUID, String> titles) {
        String title = titles.get(loan.getBookId());
        if (title == null) {
            throw new BookNotFoundException(loan.getBookId());
        }
        Long lateFee = loan.isReturned() ? loan.lateFee() : null;
        return new LoanHistoryItem(loan.getId(), title, loan.getLoanedAt(), loan.getReturnedAt(), lateFee);
    }
}

