package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class LoanHistoryIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void history_includes_returned_and_active_loans_newest_first() throws Exception {
        String memberId = registerMember();
        String oldestLoanId = loan(registerBook("Clean Code"), memberId, "2026-03-01");
        String middleLoanId = loan(registerBook("Refactoring"), memberId, "2026-03-02");
        loan(registerBook("Effective Java"), memberId, "2026-03-10");

        mockMvc.perform(post("/loans/{loanId}/return", oldestLoanId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2026-03-05\"}"))
                .andExpect(status().isOk());
        mockMvc.perform(post("/loans/{loanId}/return", middleLoanId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2026-03-05\"}"))
                .andExpect(status().isOk());

        mockMvc.perform(get("/members/{memberId}/loans/history", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(3))
                .andExpect(jsonPath("$[0].title").value("Effective Java"))
                .andExpect(jsonPath("$[0].loanedAt").value("2026-03-10"))
                .andExpect(jsonPath("$[0].returnedAt").value((Object) null))
                .andExpect(jsonPath("$[0].lateFee").value((Object) null))
                .andExpect(jsonPath("$[1].title").value("Refactoring"))
                .andExpect(jsonPath("$[1].returnedAt").value("2026-03-05"))
                .andExpect(jsonPath("$[1].lateFee").value(0))
                .andExpect(jsonPath("$[2].title").value("Clean Code"))
                .andExpect(jsonPath("$[2].loanId").value(oldestLoanId));
    }

    @Test
    void returned_late_loan_shows_late_fee_and_return_date() throws Exception {
        String memberId = registerMember();
        String loanId = loan(registerBook("Clean Code"), memberId, "2026-03-02");

        mockMvc.perform(post("/loans/{loanId}/return", loanId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2026-03-21\"}"))
                .andExpect(status().isOk());

        mockMvc.perform(get("/members/{memberId}/loans/history", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].loanId").value(loanId))
                .andExpect(jsonPath("$[0].title").value("Clean Code"))
                .andExpect(jsonPath("$[0].loanedAt").value("2026-03-02"))
                .andExpect(jsonPath("$[0].returnedAt").value("2026-03-21"))
                .andExpect(jsonPath("$[0].lateFee").value(500));
    }

    @Test
    void member_without_loans_gets_empty_list() throws Exception {
        String memberId = registerMember();

        mockMvc.perform(get("/members/{memberId}/loans/history", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(0));
    }

    @Test
    void unknown_member_returns_404() throws Exception {
        mockMvc.perform(get("/members/{memberId}/loans/history", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    private String loan(String bookId, String memberId, String loanedAt) throws Exception {
        String body = "{\"bookId\":\"" + bookId + "\",\"memberId\":\"" + memberId + "\",\"loanedAt\":\"" + loanedAt + "\"}";
        String created = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(created).get("loanId").asText();
    }

    private String registerMember() throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"김민지\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }

    private String registerBook(String title) throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        JsonNode book = objectMapper.readTree(registered);
        return book.get("id").asText();
    }
}

